  /\ K_B12 = BsStartupHSC.G1 326 /\ K_B13 = BsStartupHSC.G1 327 /\ K_B16 = BsStartupHSC.G1 392
  /\ K_META = BsStartupHSC.G1 409
  /\ (forall g, K_B20 g = BsStartupHSC.G1 (if g then 409 else 410)) /\ (forall g, K_B21 g = BsStartupHSC.G1 443)
  /\ (forall g, K_B22 g = BsStartupHSC.G1 444) /\ (forall g, K_B23 g = BsStartupHSC.G1 461)
